public static str customerMobileNumberField()
{
    str query;

    query = strFmt(@"select Top 1 Locator from LogisticsElectronicAddress postalAddress
                        join DirPartyLocation partyLocation
                            on partyLocation.Location = postalAddress.Location
                            and partyLocation.Party   = %1
                        where postalAddress.IsPrimary = 0
                        and   postalAddress.IsMobilePhone = 1",

                         SysComputedColumn::returnField(tableStr(SmmContactPersonV2Entity),
                                                        dataEntityDataSourceStr(SmmContactPersonV2Entity, ContactPerson),
                                                        fieldStr(ContactPerson, Party)));

    return query;
}

public static str customerDataAreaId()
{
    str query;

    query = strFmt(@"Select top 1 DataAreaid from custtable
                        where custtable.dataAreaId = %2
                        and custtable.AccountNum = %1",
                    SysComputedColumn::returnField(tableStr(SmmContactPersonV2Entity),
                                                   dataEntityDataSourceStr(smmContactPersonV2Entity, ContactPerson),
                                                   fieldStr(ContactPerson, CustAccount)),
                    SysComputedColumn::returnField(tableStr(smmContactPersonV2Entity),
                                                   dataEntityDataSourceStr(smmContactPersonV2Entity, ContactPerson),
        fieldStr(ContactPerson, DataAreaId)));

    return query;

}
